func (checker *ProcessConnectChecker) FromProcessConnect(event *tetragon.ProcessConnect) *ProcessConnectChecker {
	if event == nil {
		return checker
	}
	if event.Process != nil {
		checker.Process = NewProcessChecker().FromProcess(event.Process)
	}
	if event.Parent != nil {
		checker.Parent = NewProcessChecker().FromProcess(event.Parent)
	}
	checker.SourceIp = stringmatcher.Full(event.SourceIp)
	if event.SourcePort != nil {
		val := event.SourcePort.Value
		checker.SourcePort = &val
	}
	checker.DestinationIp = stringmatcher.Full(event.DestinationIp)
	if event.DestinationPort != nil {
		val := event.DestinationPort.Value
		checker.DestinationPort = &val
	}
	{
		var checks []*stringmatcher.StringMatcher
		for _, check := range event.DestinationNames {
			var convertedCheck *stringmatcher.StringMatcher
			convertedCheck = stringmatcher.Full(check)
			checks = append(checks, convertedCheck)
		}
		lm := NewStringListMatcher().WithOperator(listmatcher.Ordered).
			WithValues(checks...)
		checker.DestinationNames = lm
	}
	{
		val := event.SockCookie
		checker.SockCookie = &val
	}
	if event.DestinationPod != nil {
		checker.DestinationPod = NewPodChecker().FromPod(event.DestinationPod)
	}
	checker.Protocol = NewSocketProtocolChecker(event.Protocol)
	if event.DestinationService != nil {
		checker.DestinationService = NewServiceChecker().FromService(event.DestinationService)
	}
	{
		var checks []*ProcessChecker
		for _, check := range event.Ancestors {
			var convertedCheck *ProcessChecker
			if check != nil {
				convertedCheck = NewProcessChecker().FromProcess(check)
			}
			checks = append(checks, convertedCheck)
		}
		lm := NewProcessListMatcher().WithOperator(listmatcher.Ordered).
			WithValues(checks...)
		checker.Ancestors = lm
	}
	if event.PolicyInfo != nil {
		checker.PolicyInfo = NewTNPInfoChecker().FromTNPInfo(event.PolicyInfo)
	}
	{
		val := event.ConnectionId
		checker.ConnectionId = &val
	}
	return checker
}

