// ServiceChecker implements a checker struct to check a Service field
type ServiceChecker struct {
	Name           *stringmatcher.StringMatcher           `json:"Name,omitempty"`
	Namespace      *stringmatcher.StringMatcher           `json:"Namespace,omitempty"`
	SelectorLabels map[string]stringmatcher.StringMatcher `json:"selectorLabels,omitempty"`
	Type           *ServiceKindChecker                    `json:"Type,omitempty"`
}

// NewServiceChecker creates a new ServiceChecker
func NewServiceChecker() *ServiceChecker {
	return &ServiceChecker{}
}

// Get the type of the checker as a string
func (checker *ServiceChecker) GetCheckerType() string {
	return "ServiceChecker"
}

// Check checks a Service field
func (checker *ServiceChecker) Check(event *tetragon.Service) error {
	if event == nil {
		return fmt.Errorf("%s: Service field is nil", CheckerLogPrefix(checker))
	}

	fieldChecks := func() error {
		if checker.Name != nil {
			if err := checker.Name.Match(event.Name); err != nil {
				return fmt.Errorf("Name check failed: %w", err)
			}
		}
		if checker.Namespace != nil {
			if err := checker.Namespace.Match(event.Namespace); err != nil {
				return fmt.Errorf("Namespace check failed: %w", err)
			}
		}
		{
			var unmatched []string
			matched := make(map[string]struct{})
			for key, value := range event.SelectorLabels {
				if len(checker.SelectorLabels) > 0 {
					// Attempt to grab the matcher for this key
					if matcher, ok := checker.SelectorLabels[key]; ok {
						if err := matcher.Match(value); err != nil {
							return fmt.Errorf("SelectorLabels[%s] (%s=%s) check failed: %w", key, key, value, err)
						}
						matched[key] = struct{}{}
					}
				}
			}

			// See if we have any unmatched values that we wanted to match
			if len(matched) != len(checker.SelectorLabels) {
				for k := range checker.SelectorLabels {
					if _, ok := matched[k]; !ok {
						unmatched = append(unmatched, k)
					}
				}
				return fmt.Errorf("SelectorLabels unmatched: %v", unmatched)
			}
		}
		if checker.Type != nil {
			if err := checker.Type.Check(&event.Type); err != nil {
				return fmt.Errorf("Type check failed: %w", err)
			}
		}
		return nil
	}
	if err := fieldChecks(); err != nil {
		return fmt.Errorf("%s: %w", CheckerLogPrefix(checker), err)
	}
	return nil
}

// WithName adds a Name check to the ServiceChecker
func (checker *ServiceChecker) WithName(check *stringmatcher.StringMatcher) *ServiceChecker {
	checker.Name = check
	return checker
}

// WithNamespace adds a Namespace check to the ServiceChecker
func (checker *ServiceChecker) WithNamespace(check *stringmatcher.StringMatcher) *ServiceChecker {
	checker.Namespace = check
	return checker
}

// WithSelectorLabels adds a SelectorLabels check to the ServiceChecker
func (checker *ServiceChecker) WithSelectorLabels(check map[string]stringmatcher.StringMatcher) *ServiceChecker {
	checker.SelectorLabels = check
	return checker
}

// WithType adds a Type check to the ServiceChecker
func (checker *ServiceChecker) WithType(check tetragon.ServiceKind) *ServiceChecker {
	wrappedCheck := ServiceKindChecker(check)
	checker.Type = &wrappedCheck
	return checker
}

//FromService populates the ServiceChecker using data from a Service field
func (checker *ServiceChecker) FromService(event *tetragon.Service) *ServiceChecker {
	if event == nil {
		return checker
	}
	checker.Name = stringmatcher.Full(event.Name)
	checker.Namespace = stringmatcher.Full(event.Namespace)
	// TODO: implement fromMap
	checker.Type = NewServiceKindChecker(event.Type)
	return checker
}

