// Check checks a FileDetails field
func (checker *FileDetailsChecker) Check(event *tetragon.FileDetails) error {
	if event == nil {
		return fmt.Errorf("%s: FileDetails field is nil", CheckerLogPrefix(checker))
	}

	fieldChecks := func() error {
		if checker.Str != nil {
			switch event := event.Filename.(type) {
			case *tetragon.FileDetails_Str:
				if err := checker.Str.Match(event.Str); err != nil {
					return fmt.Errorf("Str check failed: %w", err)
				}
			default:
				return fmt.Errorf("FileDetailsChecker: Str check failed: %T is not a Str", event)
			}
		}
		if checker.Inode != nil {
			if err := checker.Inode.Check(event.Inode); err != nil {
				return fmt.Errorf("Inode check failed: %w", err)
			}
		}
		if checker.ParentInode != nil {
			if err := checker.ParentInode.Check(event.ParentInode); err != nil {
				return fmt.Errorf("ParentInode check failed: %w", err)
			}
		}
		if checker.Location != nil {
			if err := checker.Location.Check(event.Location); err != nil {
				return fmt.Errorf("Location check failed: %w", err)
			}
		}
		if checker.OpenFlags != nil {
			if err := checker.OpenFlags.Check(event.OpenFlags); err != nil {
				return fmt.Errorf("OpenFlags check failed: %w", err)
			}
		}
		return nil
	}
	if err := fieldChecks(); err != nil {
		return fmt.Errorf("%s: %w", CheckerLogPrefix(checker), err)
	}
	return nil
}

